  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(255) DEFAULT NULL COMMENT '标题',
  `dynasty` varchar(10) DEFAULT NULL COMMENT '朝代',
  `writer` varchar(100) DEFAULT NULL COMMENT '作者',
  `type` varchar(100) DEFAULT NULL,
  `content` text COMMENT '内容',
  `remark` text,
  `shangxi` text,
  `audioUrl` varchar(255) DEFAULT NULL COMMENT 'audioUrl',
  `translation` text,
  PRIMARY KEY (`id`),
  UNIQUE KEY `potry_id_uindex` (`id`),
  KEY `potry_writer_index` (`writer`) COMMENT '作者',
  KEY `potry_writer_index_2` (`writer`)
) ENGINE=InnoDB AUTO_INCREMENT=10779 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

